
const WORDS=[{"id": 0, "w": "用户", "p": "yònghù", "t": "名词", "m": "người dùng", "coll": "注册用户、用户体验", "s": "这款软件非常重视用户提出的意见。"}, {"id": 1, "w": "颠球", "p": "diān qiú", "t": "动词", "m": "tung hứng (bóng)", "coll": "练习颠球、颠球技巧", "s": "他每天放学后都在操场上练习颠球。"}, {"id": 2, "w": "明星", "p": "míngxīng", "t": "名词", "m": "ngôi sao", "coll": "电影明星、体育明星", "s": "她从小就梦想成为一名电影明星。"}, {"id": 3, "w": "直播", "p": "zhíbō", "t": "动词", "m": "phát sóng trực tiếp", "coll": "现场直播、直播节目", "s": "这场比赛将通过网络进行直播。"}, {"id": 4, "w": "宝贝", "p": "bǎobèi", "t": "名词", "m": "cục cưng", "coll": "家里的宝贝、心爱的宝贝", "s": "对父母来说，每个孩子都是家里的宝贝。"}, {"id": 5, "w": "逗", "p": "dòu", "t": "动词", "m": "gây cười, chọc cười", "coll": "逗孩子笑、逗大家开心", "s": "他讲了一个有趣的故事，把大家都逗笑了。"}, {"id": 6, "w": "宣传", "p": "xuānchuán", "t": "动词", "m": "tuyên truyền", "coll": "宣传活动、宣传环保知识", "s": "同学们在校园里宣传节约用水的重要性。"}, {"id": 7, "w": "手笔", "p": "shǒubǐ", "t": "名词", "m": "sự mạnh tay, sự phô trương", "coll": "大手笔、大手笔投入", "s": "这场演出的舞台设计真是大手笔。"}, {"id": 8, "w": "推广", "p": "tuīguǎng", "t": "动词", "m": "phổ biến, mở rộng", "coll": "推广产品、推广方法", "s": "这家公司准备向更多城市推广这款新产品。"}, {"id": 9, "w": "注册", "p": "zhùcè", "t": "动词", "m": "đăng ký", "coll": "注册账号、注册会员", "s": "使用这款应用前，请先注册一个账号。"}, {"id": 10, "w": "召开", "p": "zhàokāi", "t": "动词", "m": "mời dự họp, tổ chức", "coll": "召开会议、召开座谈会", "s": "公司将于下周一召开全体员工会议。"}, {"id": 11, "w": "合作", "p": "hézuò", "t": "动词", "m": "hợp tác", "coll": "互相合作、加强合作", "s": "两所学校决定在文化交流方面加强合作。"}, {"id": 12, "w": "伙伴", "p": "huǒbàn", "t": "名词", "m": "cộng sự, đối tác", "coll": "合作伙伴、学习伙伴", "s": "他不仅是我的同事，也是我的合作伙伴。"}, {"id": 13, "w": "总裁", "p": "zǒngcái", "t": "名词", "m": "chủ tịch, president", "coll": "公司总裁、担任总裁", "s": "公司的总裁在会议上介绍了明年的发展计划。"}, {"id": 14, "w": "实现", "p": "shíxiàn", "t": "动词", "m": "thực hiện", "coll": "实现梦想、实现目标", "s": "经过多年的努力，她终于实现了自己的梦想。"}, {"id": 15, "w": "覆盖", "p": "fùgài", "t": "动词", "m": "bao trùm", "coll": "覆盖全国、覆盖范围", "s": "这家公司的服务已经覆盖了全国多个城市。"}, {"id": 16, "w": "移动", "p": "yídòng", "t": "动词", "m": "di động, di chuyển", "coll": "移动桌子、移动位置", "s": "打扫教室前，我们先把桌子移动到一边。"}, {"id": 17, "w": "通信", "p": "tōngxìn", "t": "动词／名词", "m": "sự thông tin; liên lạc", "coll": "通信设备、通信技术", "s": "这本书介绍了现代通信技术的发展过程。"}, {"id": 18, "w": "应用", "p": "yìngyòng", "t": "动词／名词", "m": "ứng dụng", "coll": "应用知识、应用于实践", "s": "我们应该把学到的知识应用到实际生活中。"}, {"id": 19, "w": "企业", "p": "qǐyè", "t": "名词", "m": "xí nghiệp, công ty", "coll": "一家企业、企业文化", "s": "这家企业非常重视员工的培训和成长。"}, {"id": 20, "w": "称霸", "p": "chēngbà", "t": "动词", "m": "xưng bá, thống trị", "coll": "称霸联赛、称霸赛场", "s": "故事里的那支球队经过不断努力，最终称霸了联赛。"}, {"id": 21, "w": "背景", "p": "bèijǐng", "t": "名词", "m": "bối cảnh", "coll": "文化背景、故事背景", "s": "了解故事的背景，有助于理解人物的选择。"}, {"id": 22, "w": "高级", "p": "gāojí", "t": "形容词", "m": "cao cấp", "coll": "高级课程、高级工程师", "s": "通过考试后，她开始学习高级汉语课程。"}, {"id": 23, "w": "副", "p": "fù", "t": "形容词", "m": "phó, phụ", "coll": "副校长、副经理", "s": "他是我们学校的副校长。"}, {"id": 24, "w": "开发", "p": "kāifā", "t": "动词", "m": "khai thác, phát triển", "coll": "开发软件、开发新产品", "s": "这支团队正在开发一款新的学习软件。"}, {"id": 25, "w": "中心", "p": "zhōngxīn", "t": "名词", "m": "trung tâm", "coll": "市中心、研究中心", "s": "这座城市的中心有一个很大的广场。"}, {"id": 26, "w": "相关", "p": "xiāngguān", "t": "动词", "m": "liên quan", "coll": "相关信息、与工作相关", "s": "请在网上查找与这个主题相关的信息。"}, {"id": 27, "w": "业务", "p": "yèwù", "t": "名词", "m": "nghiệp vụ", "coll": "办理业务、熟悉业务", "s": "为了尽快熟悉业务，她每天都认真学习。"}, {"id": 28, "w": "现实", "p": "xiànshí", "t": "名词", "m": "hiện thực", "coll": "面对现实、现实生活", "s": "遇到困难时，我们要勇敢地面对现实。"}, {"id": 29, "w": "个人", "p": "gèrén", "t": "名词", "m": "cá nhân", "coll": "个人信息、个人意见", "s": "这只是我个人的意见，并不代表公司。"}, {"id": 30, "w": "以及", "p": "yǐjí", "t": "连词", "m": "và", "coll": "老师以及学生、书籍以及杂志", "s": "活动欢迎老师、学生以及家长参加。"}, {"id": 31, "w": "程度", "p": "chéngdù", "t": "名词", "m": "trình độ, mức độ", "coll": "不同程度、理解程度", "s": "这些练习适合不同程度的汉语学习者。"}, {"id": 32, "w": "发达", "p": "fādá", "t": "形容词", "m": "phát triển", "coll": "交通发达、经济发达", "s": "这个地区交通发达，去周围的城市很方便。"}, {"id": 33, "w": "创新", "p": "chuàngxīn", "t": "动词", "m": "sáng tạo cái mới, đổi mới", "coll": "不断创新、技术创新", "s": "这家企业鼓励员工积极思考，不断创新。"}, {"id": 34, "w": "领导", "p": "lǐngdǎo", "t": "名词", "m": "lãnh đạo", "coll": "公司领导、学校领导", "s": "学校领导认真地听取了老师和学生的建议。"}, {"id": 35, "w": "地位", "p": "dìwèi", "t": "名词", "m": "địa vị, vị trí", "coll": "重要地位、社会地位", "s": "阅读在语言学习中占有重要地位。"}, {"id": 36, "w": "经营", "p": "jīngyíng", "t": "动词", "m": "kinh doanh", "coll": "经营商店、经营饭店", "s": "他的父母在这条街上经营着一家小饭店。"}, {"id": 37, "w": "销售", "p": "xiāoshòu", "t": "动词", "m": "tiêu thụ (hàng hóa)", "coll": "销售产品、销售额", "s": "这家商店主要销售当地生产的食品。"}, {"id": 38, "w": "针对", "p": "zhēnduì", "t": "动词", "m": "nhằm vào, chĩa vào", "coll": "针对问题、针对不同需求", "s": "老师针对大家的困难，调整了教学方法。"}, {"id": 39, "w": "当地", "p": "dāngdì", "t": "名词", "m": "bản địa, bản xứ", "coll": "当地居民、当地文化", "s": "旅行时，我们应该尊重当地的文化。"}, {"id": 40, "w": "代言", "p": "dàiyán", "t": "动词", "m": "phát ngôn, làm đại diện", "coll": "为品牌代言、代言广告", "s": "这家公司邀请一位运动员为新产品代言。"}, {"id": 41, "w": "华裔", "p": "huáyì", "t": "名词", "m": "người gốc Hoa", "coll": "华裔青年、华裔作家", "s": "这篇文章介绍了一位华裔作家的成长故事。"}, {"id": 42, "w": "移民", "p": "yímín", "t": "名词", "m": "dân di cư", "coll": "一位移民、移民生活", "s": "小说中的主人公是一位移民，正在适应新的生活。"}];
